const d = $('Build prompt').first().json;
let table = '| App | Reviews this week | Avg / week (prev 4) | Stars this week | Stars (prev 4) | Saying they leave | Spikes |
|---|---|---|---|---|---|---|
';
for (const [app, a] of Object.entries(d.apps)) {
  table += `| ${app} | ${a.reviews_this_week} | ${a.avg_reviews_per_week_prev_4} | ${a.avg_stars_this_week ?? '-'} | ${a.avg_stars_prev_4_weeks ?? '-'} | ${a.leaving_this_week} | ${a.spikes.join(', ') || 'none'} |
`;
}
const md = `# Weekly review digest: ${d.week}

_Generated ${d.generated} by the n8n workflow "Weekly review digest" (Gemini Flash-Lite). Source: Google Play reviews._

${table}
${$input.first().json.text}
`;
const day = d.generated.slice(0, 10);
return [{ json: { md, fileName: `digest_${day}.md` } }];
